package com.qwerty.homenet.sht;
import com.qwerty.homenet.blockentity.*;
import com.qwerty.homenet.data.*;
import com.qwerty.homenet.intercom.*;
import com.qwerty.homenet.guard.*;
import com.qwerty.homenet.analog.*;
import com.qwerty.homenet.registry.ModBlocks;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.server.level.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraftforge.common.util.FakePlayerFactory;
import net.minecraftforge.gametest.*;
import java.util.*;
@GameTestHolder(Product.ID) @PrefixGameTestTemplate(false)
public class OperationTests {
 @BeforeBatch(batch="defaultBatch") public static void zones(ServerLevel level){ZoneData.get(level).add("new SHT suite",1,-100000,-100000,100000,100000);}
 static Station home(GameTestHelper h,int x){h.setBlock(new BlockPos(x,1,3),Product.STATION.get());var s=(Station)h.getLevel().getBlockEntity(h.absolutePos(new BlockPos(x,1,3)));s.onLoad();h.assertTrue(s.kind()==DeviceRegistry.Kind.VIDEO_PHONE,"Wrong dashboard device kind");return s;}
 static ServerPlayer user(GameTestHelper h,Station s){var p=FakePlayerFactory.get(h.getLevel(),new com.mojang.authlib.GameProfile(UUID.nameUUIDFromBytes(s.getBlockPos().toString().getBytes()),"ShtTester"));p.setPos(s.getBlockPos().getX()+.5,s.getBlockPos().getY(),s.getBlockPos().getZ()+.5);p.getInventory().clearContent();return p;}
 static void tick(Station s,int count){for(int i=0;i<count;i++)ReceiverBlockEntity.serverTick(s.getLevel(),s.getBlockPos(),s.getBlockState(),s);}
 static void program(Station s,ServerPlayer p,String slot,String n,boolean remote){s.press("memory",p,remote);if(slot.length()==1)s.digit(slot,remote);else s.press(slot,p,remote);for(char c:n.toCharArray())s.digit(""+c,remote);if(s.memory)s.press("memory",p,remote);}
 static class SamsungGuard extends ReceiverBlockEntity implements GuardExchange {
  Station resident;boolean event;SamsungGuard(BlockPos at,BlockState state){super(Product.TYPE.get(),at,state);}
  public DeviceRegistry.Kind kind(){return DeviceRegistry.Kind.GUARD_CONSOLE;}public GuardSystem guardSystem(){return GuardSystem.BUS;}public String manufacturer(){return "SAMSUNG";}public String modelId(){return "test BUS endpoint";}public boolean supports(AnalogBus b){return b==AnalogBus.COMMON_8_WIRE;}
  public void onLinked(BlockPos at,String n){}public void onUnlinked(BlockPos at){}public String assignedUnit(BlockPos at){return "101-1001";}public void setEmergency(BlockPos at,String n,boolean on){event=on;}public void setSafetyEvent(BlockPos at,String n,String type,boolean on){event=on;}public void setAway(BlockPos at,String n,boolean on){}public void callFrom(ReceiverBlockEntity r,ServerPlayer p){resident=(Station)r;callState=CallState.RINGING;}public void answer(){if(resident.acceptSwitchboardCall(worldPosition))callState=CallState.CONNECTED;}
  public void reply(ServerPlayer p,String text){Intercom.say((ServerLevel)level,this,resident,p,"경비실",text);}
 }
 static SamsungGuard guard(GameTestHelper h){h.setBlock(new BlockPos(1,1,1),Product.STATION.get());var at=h.absolutePos(new BlockPos(1,1,1));var g=new SamsungGuard(at,h.getLevel().getBlockState(at));h.getLevel().setBlockEntity(g);g.onLoad();return g;}
 @GameTest(template="empty") public static void busDialAndReply(GameTestHelper h){var s=home(h,3);var p=user(h,s);s.lift(p);var g=guard(h);h.assertTrue(s.bindSwitchboard(g.getBlockPos()),"Samsung BUS binding rejected");Wire.apply(new Wire.Input(s.getBlockPos(),false,"press","guard"),p);h.assertTrue(g.getCallState()==CallState.RINGING,"Base did not signal guard");s.press("talk",p,true);g.answer();h.assertTrue(s.getCallState()==CallState.CONNECTED,"Guard answer did not connect");Wire.apply(new Wire.Input(s.getBlockPos(),true,"chat","세대 발신"),p);g.reply(p,"경비실 답신");h.assertTrue(g.conversation().stream().anyMatch(l->l.text().equals("세대 발신"))&&s.conversation().stream().anyMatch(l->l.text().equals("경비실 답신")),"Guard chat not bidirectional");s.finish();s.press("guard",p,true);g.answer();h.assertTrue(s.getCallState()==CallState.CONNECTED&&s.audio,"Cordless guard direct key failed");h.succeed();}
 @GameTest(template="empty") public static void starUsesExistingConsoleBusRejectsKocom(GameTestHelper h){var s=home(h,3);var p=user(h,s);h.setBlock(new BlockPos(1,1,1),ModBlocks.AM_10KP.get());h.assertTrue(!s.bindSwitchboard(h.absolutePos(new BlockPos(1,1,1))),"Samsung bound KOCOM BUS");s.press("mode",p,false);s.setUnit(p,"102-1002");h.setBlock(new BlockPos(1,1,1),ModBlocks.GUARD_CONSOLE.get());var g=(ReceiverBlockEntity)h.getLevel().getBlockEntity(h.absolutePos(new BlockPos(1,1,1)));g.onLoad();s.lift(p);s.press("guard",p,true);h.assertTrue(g.getCallState()==CallState.RINGING,"Real STAR guard did not ring");g.answer();s.say(p,"STAR 양방향",true);h.assertTrue(g.conversation().stream().anyMatch(l->l.text().equals("STAR 양방향")),"STAR audio not active after remote guard key");h.succeed();}
 @GameTest(template="empty") public static void cameraAnswerVideoAndTimeout(GameTestHelper h){var s=home(h,3);var p=user(h,s);s.lift(p);h.setBlock(new BlockPos(6,1,3),ModBlocks.DOOR_STATION.get());var c=(DoorStationBlockEntity)h.getLevel().getBlockEntity(h.absolutePos(new BlockPos(6,1,3)));h.assertTrue(c.toggleReceiver(s.getBlockPos()),"Camera link rejected");c.startCall("");h.assertTrue(c.getBlockPos().equals(s.camera()),"Camera image missing");s.press("talk",p,true);s.say(p,"현관 통화",true);h.assertTrue(c.isConnected()&&c.getLog().stream().anyMatch(l->l.text().equals("현관 통화")),"Door answer/chat failed");s.finish();c.startCall("");tick(s,301);h.assertTrue(s.getCallState()==CallState.IDLE&&!c.isInCall(),"15-second unanswered timeout failed");h.succeed();}
 @GameTest(template="empty") public static void inventoryCradleAndFourWalls(GameTestHelper h){var s=home(h,3);var p=user(h,s);for(var facing:List.of(Direction.NORTH,Direction.SOUTH,Direction.EAST,Direction.WEST)){s.lift(p);var stack=p.getInventory().getItem(0);p.getInventory().setItem(0,ItemStack.EMPTY);p.getInventory().setItem(12,stack);var state=s.getBlockState().setValue(com.qwerty.homenet.block.WallMountedBlock.FACING,facing);double across=(220-523.5)*(.5/824);double x=facing==Direction.NORTH?.5-across:facing==Direction.SOUTH?.5+across:.5;double z=facing==Direction.EAST?.5-across:facing==Direction.WEST?.5+across:.5;var at=s.getBlockPos();var hit=new net.minecraft.world.phys.BlockHitResult(new net.minecraft.world.phys.Vec3(at.getX()+x,at.getY()+.30+(700-300)*(.5/824),at.getZ()+z),facing,at,false);h.assertTrue(Product.StationBlock.cradle(state,h.getLevel(),at,hit),"Cradle detection failed "+facing);Product.STATION.get().use(state,h.getLevel(),at,p,net.minecraft.world.InteractionHand.MAIN_HAND,hit);h.assertTrue(s.docked&&stack.isEmpty(),"Empty-handed click did not dock");}h.assertTrue(s.folded,"Central antenna default not folded");h.succeed();}
 @GameTest(template="empty") public static void wirelessScopeAndOwner(GameTestHelper h){var s=home(h,3);var other=home(h,5);var p=user(h,s);s.lift(p);var stack=p.getInventory().getItem(0);h.assertTrue(s.owns(stack)&&!other.owns(stack)&&s.allowed(p,true),"Pair ownership invalid");p.setPos(s.getBlockPos().getX()+40,s.getBlockPos().getY(),s.getBlockPos().getZ());h.assertTrue(!s.allowed(p,true),"Wireless exceeded range");p.setPos(s.getBlockPos().getX()+2,s.getBlockPos().getY(),s.getBlockPos().getZ());var at=p.blockPosition();ZoneData.get(h.getLevel()).add("different parcel",2,at.getX(),at.getZ(),at.getX(),at.getZ());h.assertTrue(!s.allowed(p,true),"Wireless crossed complex");h.succeed();}
 @GameTest(template="empty") public static void phoneMemoryHoldAndTransfer(GameTestHelper h){var a=home(h,3);var b=home(h,5);var p=user(h,a);var q=user(h,b);a.lift(p);b.lift(q);program(a,p,"speaker","50001",false);program(b,q,"speaker","50002",false);a.press("talk",p,true);for(char c:"50002#".toCharArray())a.digit(""+c,true);b.press("talk",q,true);a.say(p,"전화",true);h.assertTrue(a.audio&&b.phone==3&&b.conversation().stream().anyMatch(l->l.text().equals("전화")),"Dial after talk lost audio");a.press("hold",p,false);int count=b.conversation().size();a.say(p,"보류",true);h.assertTrue(b.conversation().size()==count,"Hold leaked audio");a.press("talk",p,true);a.say(p,"재통화",true);h.assertTrue(b.conversation().stream().anyMatch(l->l.text().equals("재통화")),"Hold resume failed");a.finish();program(a,p,"3","50002",false);a.press("speaker",p,false);a.press("memory",p,false);a.digit("3",false);h.assertTrue(b.phone==2,"Base memory recall failed");h.succeed();}
 @GameTest(template="empty") public static void pinsAlarmAndPersistence(GameTestHelper h){var s=home(h,3);var p=user(h,s);program(s,p,"guard","23",false);s.press("memory",p,true);for(char c:"*#23".toCharArray())s.digit(""+c,true);program(s,p,"hold","23",false);h.assertTrue(s.paired(),"Manual PIN sequence failed");var g=guard(h);s.bindSwitchboard(g.getBlockPos());s.trigger("gas");tick(s,600);h.assertTrue(g.event,"30-second guard notification absent");s.press("stop",p,false);h.assertTrue(!s.alarm.isEmpty(),"Alarm stop removed lens");s.press("restore",p,false);h.assertTrue(s.alarm.isEmpty()&&!g.event,"Restore failed");s.press("test",p,false);s.digit("1",false);tick(s,601);h.assertTrue(!g.event&&s.test,"Trial reached real guard");s.press("channel",p,true);var copy=new Station(s.getBlockPos(),s.getBlockState());copy.load(s.saveWithoutMetadata());h.assertTrue(copy.channel==2&&copy.paired()&&copy.folded,"Persistent settings lost");h.succeed();}
 @GameTest(template="empty") public static void automaticAlarmTelephoneSequence(GameTestHelper h){var a=home(h,3);var b=home(h,5);var p=user(h,a);var q=user(h,b);a.lift(p);b.lift(q);program(a,p,"speaker","50901",false);program(b,q,"speaker","50902",false);program(a,p,"*","50902",false);a.trigger("fire");tick(a,600);h.assertTrue(b.phone==2,"Alarm did not call stored report telephone");b.press("talk",q,true);tick(a,441);h.assertTrue(b.conversation().stream().filter(v->v.text().equals("fire 경보")).count()==2&&b.conversation().stream().anyMatch(v->v.text().equals("발생지 50901")),"10s/2s/10s report sequence missing");h.succeed();}
 @GameTest(template="empty") public static void localIntercomAndModeUnlink(GameTestHelper h){var s=home(h,3);var p=user(h,s);var g=guard(h);s.bindSwitchboard(g.getBlockPos());s.press("mode",p,false);h.assertTrue(!s.bus&&s.getAnalogStation()==null&&!s.bindSwitchboard(g.getBlockPos()),"Mode change leaked BUS binding");s.lift(p);s.press("intercom",p,false);s.press("talk",p,true);s.say(p,"수화기에서 본체",true);s.say(p,"본체에서 수화기",false);h.assertTrue(s.conversation().stream().anyMatch(l->l.text().equals("수화기에서 본체"))&&s.conversation().stream().anyMatch(l->l.text().equals("본체에서 수화기")),"Local intercom missing");s.replace(p);h.assertTrue(s.docked&&s.internal==0,"Cradle did not terminate intercom");h.succeed();}
}
